// Prefer updating the theme palette over repainting every range.
// Theme tokens like 'accent1' will automatically pick up the new palette.
workbook.setColorScheme({
  name: 'Brand',
  themeColors: {
    accent1: '#1F6FEB',
    accent2: '#F97316',
    accent3: '#16A34A',
    dk1: '#0B0F19',
    lt1: '#FFFFFF',
    lt2: '#E5E7EB',
    hlink: '#2563EB',
    folHlink: '#7C3AED',
  },
});
